ValidationRule.errorConditionFormula:
AND(

OR(
AND(
TEXT( Manual_or_Scheduled_Publishing__c ) = "Manual Publishing",
Active__c == True
),
AND(
TEXT( Manual_or_Scheduled_Publishing__c ) = "Scheduled Publishing",
NOT(ISBLANK(Event_Publishing_Date_Time__c) )
)
)
,
OR(
ISBLANK( Maximum_Registration__c )
)
)
